use serde_json::Value;

pub fn solve(input: serde_json::Value) -> serde_json::Value {
    let cents = input[0].as_i64().unwrap();
    let n = input[1].as_i64().unwrap();

    let mut shares = Vec::with_capacity(n as usize);
    let mut total = cents;
    for i in 0..n {
        let share = total / (n - i);
        shares.push(share);
        total -= share;
    }

    Value::Array(shares.into_iter().map(|s| Value::Number(s.into())).collect())
}
